import { useEffect, useRef, useState, type ReactNode } from "react";
import { Toolbar } from "@kerfjs/ui/toolbar";
import { PageHeader } from "@kerfjs/ui/page-header";
import { MenuHeader } from "@kerfjs/ui/menu-header";
import { MenuItem } from "@kerfjs/ui/menu-item";
import { ResizableRegion, wireResizableRegions } from "@kerfjs/ui/resizable-region";
import "@kerfjs/ui/layout.css";
import "./ApplicationShell.css";

type Props = { workspace: ReactNode; inspector: ReactNode };
export function ApplicationShell({ workspace, inspector }: Props) {
  const root = useRef<HTMLDivElement>(null);
  const [route, setRoute] = useState("projects");
  const [phonePane, setPhonePane] = useState("workspace");
  const [inspectorSize, setInspectorSize] = useState(() => {
    try {
      const saved = Number(localStorage.getItem("workspace.inspectorWidth"));
      return Number.isFinite(saved) && saved >= 240 ? Math.min(saved, 480) : 320;
    } catch { return 320; }
  });
  useEffect(() => {
    if (!root.current) return;
    const dispose = wireResizableRegions(root.current);
    return () => dispose();
  }, []);
  function resize(size: number) {
    const next = Math.max(240, Math.min(size, 480));
    setInspectorSize(next);
    try { localStorage.setItem("workspace.inspectorWidth", String(next)); } catch {}
  }
  return <div ref={root} className="kui-layout app-shell" data-phone-pane={phonePane}>
    <a className="skip-link" href="#workspace">Skip to workspace</a>
    <Toolbar aria-label="Application">
      <strong>Studio</strong>
      <div className="phone-switch" role="group" aria-label="Visible pane">
        {["navigation", "workspace", "inspector"].map(pane =>
          <button key={pane} type="button" aria-pressed={phonePane === pane}
            onClick={() => setPhonePane(pane)}>{pane}</button>)}
      </div>
    </Toolbar>
    <div className="app-panes">
      <nav className="kui-sidebar navigation pane-scroll" aria-label="Workspace navigation">
        <section className="kui-sidebar-section">
          <MenuHeader>Workspace</MenuHeader>
          <MenuItem aria-current={route === "projects" ? "page" : undefined}
            onClick={() => { setRoute("projects"); setPhonePane("workspace"); }}>Projects</MenuItem>
          <MenuItem aria-current={route === "activity" ? "page" : undefined}
            onClick={() => { setRoute("activity"); setPhonePane("workspace"); }}>Activity</MenuItem>
        </section>
        <section className="kui-sidebar-section">
          <MenuHeader>Organization</MenuHeader>
          <MenuItem onClick={() => { setRoute("team"); setPhonePane("workspace"); }}>Team</MenuItem>
        </section>
      </nav>
      <main id="workspace" tabIndex={-1} className="workspace">
        <PageHeader title={route === "projects" ? "Projects" : route === "team" ? "Team" : "Activity"} />
        <div className="workspace-body pane-scroll">{workspace}</div>
      </main>
      <ResizableRegion className="inspector" size={inspectorSize} minSize={240} maxSize={480}
        onSizeChange={resize} aria-label="Inspector width">
        <aside className="inspector-content" aria-label="Inspector">
          <PageHeader title="Inspector" />
          <div className="inspector-body pane-scroll">{inspector}</div>
        </aside>
      </ResizableRegion>
    </div>
  </div>;
}

