html, body, #root { height: 100%; margin: 0; }
.app-shell { height: 100dvh; display: flex; flex-direction: column; overflow: hidden; }
.app-panes { display: flex; flex: 1; min-height: 0; min-width: 0; }
.navigation { flex: 0 0 15rem; }
.workspace { flex: 1; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.inspector { flex-shrink: 0; min-height: 0; }
.inspector-content { height: 100%; min-height: 0; display: flex; flex-direction: column; }
.pane-scroll { overflow: auto; overscroll-behavior: contain; min-height: 0; }
.workspace-body, .inspector-body { flex: 1; padding: var(--kui-pane-padding, 1rem); overflow-wrap: anywhere; }
.phone-switch { display: none; flex-wrap: wrap; }
button { min-height: 2.75rem; }
:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
.skip-link { position: fixed; inset-inline-start: 1rem; top: -10rem; z-index: 10; }
.skip-link:focus { top: 1rem; background: Canvas; color: CanvasText; }
@media (max-width: 48rem) {
  .phone-switch { display: flex; }
  .app-panes > * { display: none; }
  [data-phone-pane="navigation"] .navigation { display: block; flex: 1; }
  [data-phone-pane="workspace"] .workspace { display: flex; }
  [data-phone-pane="inspector"] .inspector { display: block; flex: 1; width: 100% !important; }
}
@media (prefers-reduced-motion: reduce) { .app-shell { scroll-behavior: auto; } }
